return new { dataPath = UnityEngine.Application.dataPath, playing = UnityEditor.EditorApplication.isPlaying, compiling = UnityEditor.EditorApplication.isCompiling, updating = UnityEditor.EditorApplication.isUpdating, active = UnityEngine.SceneManagement.SceneManager.GetActiveScene().path, scenes = Enumerable.Range(0, UnityEngine.SceneManagement.SceneManager.sceneCount).Select(i => new { path = UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).path, dirty = UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).isDirty }).ToArray() };
